using System.Text.Json;using Servicio.RetazoMarket.Business.DTOs.Producto;
namespace Servicio.RetazoMarket.Business.Validators;
public static class ProductoValidator {public static IReadOnlyCollection<string> Validar(CrearProductoRequest r){if(r is null)return ["La solicitud no puede ser nula."];var e=Campos(r.id_linea,r.prod_nombre,r.prod_peso,r.prod_descripcion,r.colores,r.costo_mat_prim,r.costo_mano_obra,r.porcentaje_margen_ganancia,r.porcentaje_gastos_fijos,r.porcentaje_gastos_operativos,r.es_personalizable,r.tiene_descuentos,r.prod_estado).ToList();if(r.stock_actual!=0)e.Add("El stock inicial debe ser cero; registre existencias mediante fabricación.");return e;}public static IReadOnlyCollection<string> Validar(ActualizarProductoRequest r){if(r is null)return ["La solicitud no puede ser nula."];var e=Campos(r.id_linea,r.prod_nombre,r.prod_peso,r.prod_descripcion,r.colores,r.costo_mat_prim,r.costo_mano_obra,r.porcentaje_margen_ganancia,r.porcentaje_gastos_fijos,r.porcentaje_gastos_operativos,r.es_personalizable,r.tiene_descuentos,r.prod_estado).ToList();if(r.id_producto<=0)e.Insert(0,"El id del producto es inválido.");return e;}public static IReadOnlyCollection<string> ValidarFiltro(ProductoFiltroRequest r){var e=new List<string>();if(r is null)return ["El filtro no puede ser nulo."];if(r.page_number<=0)e.Add("El número de página debe ser mayor que cero.");if(r.page_size<=0||r.page_size>100)e.Add("El tamaño de página debe estar entre 1 y 100.");if(r.precio_minimo<0||r.precio_maximo<0||r.precio_minimo>r.precio_maximo)e.Add("El rango de precios no es válido.");return e;}private static IReadOnlyCollection<string> Campos(int linea,string? n,decimal peso,string? d,JsonElement colores,decimal cm,decimal co,decimal margen,decimal gf,decimal go,string? pers,string? desc,string? estado){var e=new List<string>();if(linea<=0)e.Add("La línea es obligatoria.");if(string.IsNullOrWhiteSpace(n)||n.Trim().Length>100)e.Add("El nombre es obligatorio y admite hasta 100 caracteres.");if(peso<=0)e.Add("El peso debe ser mayor que cero.");if(string.IsNullOrWhiteSpace(d)||d.Trim().Length>500)e.Add("La descripción es obligatoria y admite hasta 500 caracteres.");if(!ColoresValidos(colores))e.Add("Colores debe ser un arreglo JSON de textos no vacíos y sin duplicados.");if(cm<0||co<0)e.Add("Los costos no pueden ser negativos.");if(margen<0||margen>=100)e.Add("El margen debe estar entre 0 inclusive y 100 exclusivo.");if(gf<0||gf>100||go<0||go>100)e.Add("Los porcentajes de gastos deben estar entre 0 y 100.");if(pers?.Trim().ToUpperInvariant() is not("S" or "N")||desc?.Trim().ToUpperInvariant() is not("S" or "N"))e.Add("Los indicadores deben ser S o N.");if(estado?.Trim().ToUpperInvariant() is not("ACT" or "INA"))e.Add("El estado debe ser ACT o INA.");return e;}private static bool ColoresValidos(JsonElement j){if(j.ValueKind!=JsonValueKind.Array)return false;var s=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var x in j.EnumerateArray()){if(x.ValueKind!=JsonValueKind.String||string.IsNullOrWhiteSpace(x.GetString())||!s.Add(x.GetString()!.Trim()))return false;}return true;}}
